87	export function isLoggedIntoCloud(): boolean {
88	  // Check if user has authenticated with Promptfoo Cloud
89	  // This supports both interactive (email-based) and non-interactive (API key) authentication
90	  // CI environments can authenticate via API keys, so we no longer exclude CI
91	  const cloudConfig = new CloudConfig();
92	  return cloudConfig.isEnabled();
