68	  constructor() {
69	    const savedConfig = readGlobalConfig()?.cloud || {};
70	    this.config = {
71	      appUrl: savedConfig.appUrl || 'https://www.promptfoo.app',
72	      apiHost: savedConfig.apiHost,
73	      apiKey: savedConfig.apiKey,
74	      sharing: savedConfig.sharing,
