166	  saveValidatedApiToken(
167	    token: string,
168	    apiHost: string,
169	    user: CloudUser,
170	    app: CloudApp,
171	    hasActiveLicense?: boolean,
172	  ): void {
173	    this.setApiKey(token);
174	    this.setApiHost(apiHost);
175	    this.setAppUrl(app.url);
176	    if (typeof hasActiveLicense === 'boolean') {
177	      const createdAt = user?.createdAt ? new Date(user.createdAt) : null;
178	      const isGrandfathered = createdAt != null && createdAt < SHARING_CUTOFF_DATE;
179	      this.setSharing(hasActiveLicense || isGrandfathered);
180	    }
181	  }
