65	export function importCommand(program: Command) {
66	  program
67	    .command('import <file>')
68	    .description('Import an eval record from a JSON file')
69	    .option('--new-id', 'Generate a new eval ID instead of preserving the original')
70	    .option('--force', 'Replace existing eval with the same ID')
71	    .action(async (file, cmdObj) => {
72	      const db = getDb();
73	      let evalId: string;
74	      try {
75	        const fileContent = fs.readFileSync(file, 'utf-8');
76	        const evalData = JSON.parse(fileContent);
77	
78	        // Extract fields from correct locations (v3 export format)
79	        const importId = extractEvalId(evalData);
80	        const importCreatedAt = extractCreatedAt(evalData);
81	        const importAuthor = extractAuthor(evalData);
82	
83	        // Check for collision if not forcing new ID
84	        if (importId && !cmdObj.newId) {
85	          const existing = await Eval.findById(importId);
86	          if (existing) {
87	            if (cmdObj.force) {
88	              logger.info(`Replacing existing eval ${importId}`);
89	              await existing.delete();
90	            } else {
91	              logger.error(
92	                `Eval ${importId} already exists. Use --new-id to import with a new ID, or --force to replace it.`,
93	              );
94	              process.exitCode = 1;
95	              return;
96	            }
97	          }
98	        }
99	
100	        if (evalData.results.version === 3) {
101	          logger.debug('Importing v3 eval');
102	
103	          // Derive vars from results for round-trip fidelity
104	          const vars = deriveVarsFromResults(evalData.results.results || []);
105	
106	          const evalRecord = await Eval.create(evalData.config, evalData.results.prompts, {
107	            id: cmdObj.newId ? undefined : importId,
108	            createdAt: importCreatedAt,
109	            author: importAuthor,
110	            completedPrompts: evalData.results.prompts,
111	            vars,
112	          });
113	          await EvalResult.createManyFromEvaluateResult(evalData.results.results, evalRecord.id);
114	          evalId = evalRecord.id;
115	        } else {
116	          logger.debug('Importing v2 eval');
117	          evalId = cmdObj.newId
118	            ? createEvalId(importCreatedAt)
119	            : importId || createEvalId(importCreatedAt);
120	          await db
121	            .insert(evalsTable)
122	            .values({
123	              id: evalId,
124	              createdAt: importCreatedAt.getTime(),
125	              author: importAuthor,
126	              description: evalData.description || evalData.config?.description,
127	              results: evalData.results,
128	              config: evalData.config,
129	            })
130	            .run();
131	        }
132	
133	        logger.info(`Eval with ID ${evalId} has been successfully imported.`);
134	
135	        telemetry.record('command_used', {
136	          name: 'import',
137	          evalId,
138	          newId: cmdObj.newId || false,
139	          force: cmdObj.force || false,
140	        });
141	      } catch (error) {
142	        logger.error(`Failed to import eval: ${error}`);
143	        process.exitCode = 1;
144	      }
145	    });
146	}
